#include <iostream>
#include <vector>
template <typename T>
class Expression {
public:
  virtual ~Expression() = default;
  virtual T evaluate() const = 0;
};
template <typename T>
class AddExpression : public Expression<T> {
private:
  const Expression<T>& lhs_;
  const Expression<T>& rhs_;
public:
  AddExpression(const Expression<T>& lhs, const Expression<T>& rhs) : lhs_(lhs), rhs_(rhs) {}
  T evaluate() const override { return lhs_.evaluate() + rhs_.evaluate(); }
};
template <typename T>
AddExpression<T> operator+(const Expression<T>& lhs, const Expression<T>& rhs) {
  return AddExpression<T>(lhs, rhs);
}
template <typename T>
class ValueExpression : public Expression<T> {
private:
  T value_;
public:
  ValueExpression(const T& value) : value_(value) {}
  T evaluate() const override { return value_; }
};
int main() {
  ValueExpression<double> a(10.0), b(5.0);
  AddExpression<double> sum(a,b);
  std::cout << sum.evaluate() << std::endl; // Evaluation happens here
  return 0;
}
